contract_probe.before_cmd:
echo '#define Py_LIMITED_API 0x030f0000
#include <Python.h>
#include <critical_section.h>
#ifdef Py_BEGIN_CRITICAL_SECTION
exists
#endif' | gcc -E -I include_before -

contract_probe.after_cmd:
echo '#define Py_LIMITED_API 0x030f0000
#include <Python.h>
#include <critical_section.h>
#ifdef Py_BEGIN_CRITICAL_SECTION
exists
#endif' | gcc -E -I include -
